            pronunciationBn = "রব্বানা- লা-তুআ-খিয্না য় ইন্নাসী য় না-আও আখ্ত্বোয়ানা-, রব্বানা- অলা-তাহ্মিল্ ‘আলাইনায় ইছরান কামা-হামাল্তাহূ ‘আলাল্লাযীনা মিন্ ক্বাব্লিনা-, রব্বানা- অলা-তুহাম্মিল্না- মা-লা-ত্বোয়া-ক্বাতা লানা-বিহ্;অ’ফু ‘আন্না-অর্গ্ফি লানা- র্অহাম্না- আন্তা মাওলা-না- ফান্ছুরনা- ‘আলাল্ ক্বাওমিল্ কা-ফিরীন্",
            meaningBn = "হে আমাদের রব! আমরা যদি ভুলে যাই, অথবা ভুল করি তাহলে আপনি আমাদেরকে পাকড়াও করবেন না। হে আমাদের রব, আমাদের উপর বোঝা চাপিয়ে দেবেন না, যেমন আমাদের পূর্ববর্তীদের উপর চাপিয়ে দিয়েছেন। হে আমাদের রব, আপনি আমাদেরকে এমন কিছু বহন করাবেন না, যার সামর্থ্য আমাদের নেই। আর আপনি আমাদেরকে মার্জনা করুন এবং আমাদেরকে ক্ষমা করুন, আর আমাদের উপর দয়া করুন। আপনি আমাদের অভিভাবক। অতএব আপনি কাফির সমপ্রদায়ের বিরুদ্ধে আমাদেরকে সাহায্য করুন।",
            virtuesBn = "সহীহ হাদীস থেকে জানা যায়-আব্দুল্লাহ ইবনে আব্বাস (রা.) থেকে বর্ণিত। তিনি বলেছেন, একদিন জিবরীল (আ.) নবী (সা.)-এর কাছে বসা ছিলেন। সেই সময় তিনি উপর দিক থেকে দরজা খোলার একটা প্রচন্ড আওয়াজ শুনতে পেয়ে মাথা উঠিয়ে বললেন, এটি আসমানের একটি দরজা। আজকেই এটি খোলা হলো-ইতিপূর্বে আর কখনো খোলা হয়নি। আর এই দরজা দিয়ে একজন ফেরেশতা পৃথিবীতে নেমে আসলেন। আজকের এই দিনের আগে তিনি আর কখনো পৃথিবীতে আসেননি। তারপর তিনি সালাম দিয়ে বললেন, আপনি আপনাকে দেওয়া দুটি নূর বা আলোর সুসংবাদ গ্রহন করুন। আপনার পূর্বে আর কোন নবীকে তা দেয়া হয়নি। আর এই দুইটি নূর হলো ফাতিহাতুল কিতাব বা সূরা ফাতিহা এবং সূরা বাকারার শেষাংশ। এর যে কোন হরফ আপনি পড়বেন। তার মধ্যকার প্রার্থিত বিষয় আপনাকে দেয়া হবে-(সহীহ মুসলিম-৩য় খন্ড,আল-কুরআনের মর্যাদা অধ্যায়, হাদীস নং-১৭৫৪)। ফলে এ দু'আ আল্লাহ তা'আলার পক্ষ থেকে রাসূলুল্লাহ(সা.)-কে প্রদানকৃত দু'টি বিশেষ নূরের মধ্যকার একটি নূরের অংশ বিশেষ। এ দু'আ শেষে 'আমীন' বললে প্রার্থিত বিষয়গুলো কবুল করা হয় বলেও হাদীসে উল্লেখ রয়েছে।\r\nএছাড়াও সহীহ হাদীসে রয়েছে-আবু মাসউদ আল-আনসারী (রা.) থেকে বর্ণিত। তিনি বলেন, রাসূল (সা.) বলেছেন: যে ব্যাক্তি রাতে সূরা আল বাকারার শেষ দুই আয়াত তিলওয়াত করবে তা তার সে রাতের জন্যে যথেষ্ট হবে - (সহীহ আল-বুখারী-৪র্থ খন্ড, কিতাবু ফাযায়েল কুরআন-কুরআনের ফযীলত অধ্যায়, হাদীস নং-২৮১৭)। অন্য সহীহ হাদীস-নোমান ইবনে বশীর (রা.) থেকে বর্ণিত। তিনি বলেন, রাসূল (সাঃ) বলেছেন, আল্লাহ আসমান যমীন সৃষ্টির দুই হাজার বছর পূর্বে একটি কিতাব লিখেছেন। সেই কিতাব থেকে দুটি আয়াত নাযিল করা হয়েছে। সেই দুইটি আয়াতের মাধ্যেমেই সূরা আল বাকারা সমাপ্ত করা হয়েছে। যে ঘরে তিন রাত এ দুইটি আয়াত তিলওয়াত করা হয় শয়তান সেই ঘরের কাছে আসতে পারে না - (জামে আত-তিরমিযী-৫ম খন্ড, আবওয়াবু ফাদাইলিল কুরআন-কুরআনের ফযীলত অধ্যায়, হাদীস নং-২৮১৮)",
